import React from 'react';

import {
  addHikingRadish,
  deleteHikingRadish,
  getHikingRadish,
} from '@apps/Hiking/@services/hikingRadish.service';
import { IHikingRadish } from '@apps/Hiking/@types/hikingRadish.types';
import { selectHikerAsync } from '@components/HikerSelector/hikerSelectHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

const HikingRadish: React.FC<{ id_hiking: number }> = ({ id_hiking }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IHikingRadish[]>([]);

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getHikingRadish(id_hiking);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [id_hiking]);

  React.useEffect(() => {
    load();
  }, [load]);

  if (isLoading) return <PohLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const handleAdd = async () => {
    try {
      const selectedHiker = await selectHikerAsync(id_hiking);
      const ok = await confirmModal2(`Точно?`);
      if (!ok) return;
      await addHikingRadish({ id_hiking, id_user: selectedHiker.idUser });
      notificationHelper.success('Добавлен редиска');
      load();
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };
  const handleDelete = async (item: IHikingRadish) => {
    try {
      const ok = await confirmModal2(
        `Удалить редиску ${[item.user.name, item.user.surname].join(' ')}?
        После этого ему будет доступна возможность присоединиться к походу.`,
      );
      if (!ok) return;
      await deleteHikingRadish({ id_hiking, id: item.id });
      notificationHelper.success('Удалено');
      load();
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };

  return (
    <div>
      <h5 className="mb-3">
        <PohButton className="float-end" size={ButtonSize.Small} onClick={handleAdd}>
          Добавить отказ
        </PohButton>
        Отказы от участия в походе
      </h5>
      {!data.length && <Empty>Тут никого...</Empty>}
      <PohList
        data={data.map((item) => {
          return {
            key: item.id,
            children: (
              <div className="d-flex">
                <PohAva
                  src={item.user.photo}
                  alt={[item.user.name, item.user.surname].join(' ')}
                  className="me-2"
                />
                <div>
                  <strong className="d-block">
                    {[item.user.name, item.user.surname].join(' ')}
                  </strong>
                  <small className="text-muted d-block">
                    {item.date.toLocaleString()}
                    {item.isHarakiri && <sup className=" text-success"> harakiri</sup>}
                  </small>
                  <small className="text-info">
                    <em>{item.comment}</em>
                  </small>
                </div>
                <aside className="ms-auto">
                  <PohButton icon={IconsEnum.trash} onClick={() => handleDelete(item)} />
                </aside>
              </div>
            ),
          };
        })}
      />
    </div>
  );
};

export default HikingRadish;
