import React, { FormEvent } from 'react';

import { getInputDate, getSQLDate } from '@helpers/dateHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';
import { showModal } from '@ui-kit/Modal';

import { addVacancy, editVacancy } from '../../../@services/hikingPositionsAndVacancies.service';
import {
  IHikingVacancyAddDto,
  IHikingVacancyUpdateDto,
} from '../../../@types/DTO/hikingPositionsAndVacancies.dto.types';
import { IHikingData } from '../../../@types/hiking.types';
import { IHikingVacancy } from '../../../@types/hikingPositionsAndVacancies.types';

interface IVacancyEditModalProps {
  data: IHikingVacancy;
  hikingData: IHikingData;
  onSave: (data: IHikingVacancy) => void;
  onCancel: () => void;
}

function EditModal({ onSave, onCancel, data, hikingData }: IVacancyEditModalProps) {
  const [editData, setEditData] = React.useState<IHikingVacancy>(data);
  const [loading, setLoading] = React.useState(false);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setLoading(true);
    if (editData.id > 0) {
      const dataForSave: IHikingVacancyUpdateDto = {
        id: data.id,
        id_hiking: hikingData.id,
        comment: editData.comment,
        deadline: getSQLDate(editData.deadline),
        is_active: editData.isActive ? 1 : 0,
      };
      const success = await editVacancy(dataForSave);
      success && onSave(editData);
    } else {
      const dataForSave: IHikingVacancyAddDto = {
        id_hiking: hikingData.id,
        id_position: data.position.id,
        comment: editData.comment,
        deadline: getSQLDate(editData.deadline),
      };
      const id = await addVacancy(dataForSave);
      id && onSave({ ...editData, id });
    }
  };

  return (
    <form onSubmit={handleSubmit} style={{ minWidth: 400 }}>
      <PohInput
        horizontal
        required
        type={InputTypes.date}
        label="Срок"
        value={getInputDate(editData.deadline, true)}
        onChange={(value) => setEditData((cur) => ({ ...cur, deadline: new Date(value) }))}
        max={getInputDate(hikingData.start)}
        labelGrid={3}
        inputGrid={9}
        disabled={loading}
        wrapperClassName="mb-2"
      />
      <PohInput
        horizontal
        labelGrid={3}
        inputGrid={9}
        label="Комментарий"
        value={editData?.comment}
        onChange={(value) => setEditData((cur) => ({ ...cur, comment: value }))}
        disabled={loading}
        wrapperClassName="mb-2"
      />
      <PohRow>
        <PohCol sm={3} />
        <PohCol sm={9}>
          <PohCheckbox
            disabled={loading}
            checked={editData.isActive}
            onChange={(checked) => setEditData((cur) => ({ ...cur, isActive: checked }))}
            label="Активна"
          />
        </PohCol>
      </PohRow>

      <footer className="text-end mt-3">
        <PohButton disabled={loading} variant={ButtonVariant.Secondary} onClick={onCancel}>
          Отмена
        </PohButton>
        <PohButton disabled={loading} variant={ButtonVariant.Primary} type="submit">
          {data.id ? 'Сохранить' : 'Добавить'}
        </PohButton>
      </footer>
    </form>
  );
}

export const addOrChangeVacancyAsync = (
  vacancy: IHikingVacancy,
  hikingData: IHikingData,
): Promise<IHikingVacancy> => {
  return new Promise((res) => {
    showModal({
      size: 'lg',
      children: (clos: any) => (
        <EditModal
          data={vacancy}
          hikingData={hikingData}
          onSave={(up) => {
            res(up);
            clos();
          }}
          onCancel={clos}
        />
      ),
    });
  });
};

export default EditModal;
