import React from 'react';

import clsx from 'clsx';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import { getEmptyScheduleItem } from '@apps/Hiking/@mappers/hikingSchedule.mapper';
import {
  addHikingSchedule,
  deleteHikingSchedule,
  getHikingSchedule,
  switchScheduleDays,
  updateHikingSchedule,
} from '@apps/Hiking/@services/hikingSchedule.service';
import { IHikingScheduleItem } from '@apps/Hiking/@types/hiking.baseTypes';
import { showScheduleEditModalAsync } from '@apps/Hiking/schedule/components/ScheduleEditModal/scheduleModalHelper';
import { getBaseRouteDataAsync, IBaseRouteData } from '@apps/Routes/@services/routes.service';
import HorizontalScrollable from '@components/HorizontalScrollable';
import PageHeader from '@components/PageHeader';
import { getSQLDate } from '@helpers/dateHelper';
import { defaultMapCoordinates } from '@helpers/leafletHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import PohLoader from '@ui-kit/Loader';

import ScheduleDaySun from './ScheduleDaySun';
import ScheduleHour from './ScheduleHour';
import ScheduleItemDraggable from './ScheduleItemDraggable';
import { selectTwoDatesAsync } from './ScheduleSwitchDates';
import styles from './styles.module.less';

const HikingEditSchedule: React.FC = () => {
  const hikingContext = React.useContext(HikingContext);
  const [data, setData] = React.useState<IHikingScheduleItem[]>([]);
  const [routeInfo, setRouteInfo] = React.useState<IBaseRouteData>();
  const [minDate, setMinDate] = React.useState<Date>();
  const [maxDate, setMaxDate] = React.useState<Date>();
  const [isLoading, setIsLoading] = React.useState(false);
  const [error, setError] = React.useState<Error>();

  const lastStartsForDayRef = React.useRef<{
    [onlyDateStr: string]: { start: Date; finish: Date };
  }>({});

  React.useEffect(() => {
    const start = async () => {
      try {
        if (!hikingContext?.id) throw new Error('need hiking context first');
        setIsLoading(true);
        const res = await getHikingSchedule(hikingContext.id);
        setData(res);
        if (hikingContext.route.id) {
          const res1 = await getBaseRouteDataAsync(hikingContext.route.id);
          setRouteInfo(res1);
        }
        let miDate = hikingContext.start;
        let maDate = hikingContext.finish;
        res.forEach((r) => {
          const dateStr = r.start.toLocaleDateString();
          if (!lastStartsForDayRef.current[dateStr])
            lastStartsForDayRef.current[dateStr] = {
              start: r.start,
              finish: r.finish,
            };
          if (lastStartsForDayRef.current[dateStr].start < r.start) {
            lastStartsForDayRef.current[dateStr].start = r.start;
          }
          if (lastStartsForDayRef.current[dateStr].finish < r.finish) {
            lastStartsForDayRef.current[dateStr].finish = r.finish;
          }

          if (r.start <= miDate) miDate = r.start;
          if (r.finish >= maDate) maDate = r.finish;
        });

        setMinDate(miDate);
        setMaxDate(maDate);
      } catch (er) {
        setError(er as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [hikingContext?.id]);

  if (isLoading) return <PohLoader />;
  if (error) return <div>{error.message}</div>;

  const handleAdd = async (start: Date, finish: Date) => {
    if (!hikingContext?.route?.id) return;
    const res = await showScheduleEditModalAsync({
      scheduleItem: getEmptyScheduleItem({ start, finish }),
      hikingData: hikingContext,
    });
    setData((cur) => [...cur, res]);
    const dateStr = res.start.toLocaleDateString();
    if (!lastStartsForDayRef.current[dateStr])
      lastStartsForDayRef.current[dateStr] = {
        start: res.start,
        finish: res.finish,
      };

    lastStartsForDayRef.current[dateStr].start = res.start;

    lastStartsForDayRef.current[dateStr].finish = res.finish;

    notificationHelper.success('Добавлено');
  };

  const handleRemove = (item: IHikingScheduleItem) => {
    hikingContext?.id &&
      confirm('Delete?') &&
      deleteHikingSchedule(hikingContext.id, item.id).then(() => {
        notificationHelper.success('Удалено');
        setData((cur) => cur.filter((r) => r.id !== item.id));
      });
  };

  const handleSwitchDays = async (d1D?: Date) => {
    if (!hikingContext) return;
    const { d1, d2 } = await selectTwoDatesAsync({ d1: d1D });
    switchScheduleDays(hikingContext.id, getSQLDate(d1), getSQLDate(d2));
  };

  if (!hikingContext || !maxDate || !minDate) return null;

  const daysCount = Math.ceil((maxDate.getTime() - minDate.getTime()) / 86400000);
  return (
    <section className="p-3">
      <PageHeader title="Расписание/План">
        <PohButton size={ButtonSize.Small} onClick={() => handleSwitchDays()}>
          Поменять дни местами
        </PohButton>
      </PageHeader>
      <HorizontalScrollable style={{ overflowY: 'auto', maxHeight: 480 }}>
        <div
          style={{
            display: 'grid',
            gridTemplateColumns: `auto ${Array(daysCount).fill('1fr').join(' ')} auto`,
          }}
        >
          <PohButton
            onClick={() => {
              setMinDate((c) => (!c ? c : new Date(c?.getTime() - 86400000)));
            }}
            className={styles.buttonBefore}
            size={ButtonSize.Small}
          >
            Добавить день до
          </PohButton>
          {Array(daysCount)
            .fill('hikingDay')
            .map((_, i) => {
              const d = new Date(minDate.getTime() + 86400000 * i);
              const startOfDay = new Date(d.getFullYear(), d.getMonth(), d.getDate(), 0, 0, 0, 0);
              const endOfDay = new Date(
                d.getFullYear(),
                d.getMonth(),
                d.getDate(),
                23,
                59,
                59,
                999,
              );

              const items = data.filter((p) => {
                return p.start <= endOfDay && p.finish >= startOfDay;
              });

              return (
                <div
                  key={i}
                  style={{
                    width: `minmax(${100 / daysCount}%, max-content)`,
                  }}
                  className={clsx(
                    'border-end p-2 flex-grow-0 flex-shrink-0',
                    i === 0 && 'border-start',
                  )}
                >
                  <header
                    title={d.toLocaleDateString('default', { weekday: 'long' })}
                    className={clsx(
                      'd-flex align-items-center justify-content-center position-sticky',
                      styles.header,
                    )}
                    style={{ top: 0 }}
                    onDoubleClick={() => handleSwitchDays(d)}
                  >
                    <span className="text-muted">
                      {d.toLocaleDateString('default', { weekday: 'short' }).toUpperCase()}
                    </span>
                    &nbsp;
                    <strong>{d.toLocaleDateString()}</strong>
                  </header>
                  <div className="position-relative">
                    <ScheduleDaySun
                      date={d}
                      coords={[
                        routeInfo?.routeData?.bounds?.[0]?.[0] ?? defaultMapCoordinates[0],
                        /*Number*/ routeInfo?.routeData?.bounds?.[0]?.[1] ??
                          defaultMapCoordinates[1],
                      ]}
                    />
                    {Array(24)
                      .fill('')
                      .map((__, h) => {
                        return (
                          <ScheduleHour
                            key={h}
                            hour={h}
                            onDropSchedule={(id, copy, mi) => {
                              console.info({ id, copy, mi });
                              const it = data.find((p) => p.id === id);
                              if (!it || !hikingContext?.id) return;
                              const duration = it.finish.getTime() - it.start.getTime();
                              if (copy) {
                                const start = new Date(
                                  d.getFullYear(),
                                  d.getMonth(),
                                  d.getDate(),
                                  h,
                                  mi,
                                );

                                addHikingSchedule(hikingContext.id, {
                                  ...it,
                                  start,
                                  finish: new Date(start.getTime() + duration),
                                  id: 0,
                                }).then((res) => {
                                  setData((cur) => [...cur, res]);
                                  notificationHelper.success('Добавлено');
                                });

                                return;
                              }

                              const start = new Date(
                                d.getFullYear(),
                                d.getMonth(),
                                d.getDate(),
                                h,
                                mi,
                              );
                              const finish = new Date(start.getTime() + duration);
                              updateHikingSchedule(hikingContext.id, {
                                ...it,
                                start,
                                finish,
                              }).then((up) => {
                                notificationHelper.success('Обновлено');
                                setData((cur) => cur.map((r) => (r.id === it.id ? up : r)));
                              });
                            }}
                            onClick={() => {
                              handleAdd(
                                new Date(d.getFullYear(), d.getMonth(), d.getDate(), h, 0),
                                new Date(d.getFullYear(), d.getMonth(), d.getDate(), h + 1, 0),
                              );
                            }}
                          />
                        );
                      })}
                    {items.map((item) => {
                      return (
                        <ScheduleItemDraggable
                          key={item.id}
                          item={item}
                          date={d}
                          draggable
                          onContextMenu={() => {
                            handleRemove(item);
                          }}
                          onClick={() => {
                            showScheduleEditModalAsync({
                              hikingData: hikingContext,
                              scheduleItem: item,
                            }).then((up) => {
                              notificationHelper.success('Обновлено');
                              setData((cur) => cur.map((r) => (r.id === item.id ? up : r)));
                            });
                          }}
                          onChangeItem={(patch) => {
                            updateHikingSchedule(hikingContext.id, {
                              ...item,
                              ...patch,
                            }).then((up) => {
                              notificationHelper.success(`Обновлено ${Object.keys(patch)}`);
                              setData((cur) => cur.map((r) => (r.id === item.id ? up : r)));
                            });
                          }}
                        />
                      );
                    })}
                  </div>
                </div>
              );
            })}
          <PohButton
            onClick={() => {
              setMaxDate((c) => (!c ? c : new Date(c?.getTime() + 86400000)));
            }}
            className={styles.buttonAfter}
            size={ButtonSize.Small}
          >
            Добавить день после
          </PohButton>
        </div>
      </HorizontalScrollable>
    </section>
  );
};

export default HikingEditSchedule;
