import React from 'react';

import Brush from '@pohodnik/icons/svg/Tools/Brush';
import CodeSlash from '@pohodnik/icons/svg/Typography/CodeSlash';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import WysiwygEditor from '@components/WysiwygEditor';
import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput from '@ui-kit/Input';
import InputTypes from '@ui-kit/Input/InputTypes';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { getHikingFieldsAsync, setHikingFieldAsync } from '../../@services/hiking.service';

const HikingEditText: React.FC = () => {
  const hikingContext = React.useContext(HikingContext);
  const [text, setText] = React.useState('');
  const [initText, setInitText] = React.useState('');
  const [isSrc, setIsSrc] = React.useState(false);

  React.useEffect(() => {
    const init = async () => {
      if (!hikingContext?.id) return;
      const { text: initTextS } = await getHikingFieldsAsync(hikingContext?.id, 'text');
      setText(initTextS ?? '');
      setInitText(initTextS ?? '');
    };
    init();
  }, [hikingContext?.id]);

  const handleSave = () => {
    if (!hikingContext?.id) return;

    setHikingFieldAsync(hikingContext.id, 'text', text)
      .catch(err)
      .then(() => {
        success('Сохранено');
        setInitText(text);
      });
  };

  if (!hikingContext) return <div>Wrong hiking context</div>;

  return (
    <section className="p-3">
      <PohRow>
        <PohCol sm={6}>
          <h5 className="mb-3">Описание похода</h5>
        </PohCol>
        <PohCol sm={6} className="text-end">
          <PohButton
            title={isSrc ? 'Переключиться на редактор' : 'Править исходный код'}
            icon
            active={isSrc}
            onClick={() => setIsSrc((c) => !c)}
          >
            {isSrc ? <Brush /> : <CodeSlash />}
          </PohButton>

          {text !== initText && (
            <PohButton variant={ButtonVariant.Success} onClick={handleSave} className="ms-3">
              Сохранить
            </PohButton>
          )}
        </PohCol>
      </PohRow>
      {!isSrc && <WysiwygEditor html={text} onChange={setText} placeholder="Введите описание" />}
      {isSrc && (
        <PohInput
          style={{ minHeight: 420 }}
          type={InputTypes.textarea}
          value={text}
          onChange={setText}
          placeholder="Введите описание"
        />
      )}
    </section>
  );
};

export default HikingEditText;
