import React from 'react';

import { HikingContext } from '@apps/Hiking/@contexts/hikingContext';
import PageLoader from '@components/PageLoader';
import { success } from '@helpers/notificationHelper';
import PohButton from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohList from '@ui-kit/List';
import { confirmModal } from '@ui-kit/Modal';

import { addOrChangeVacancyAsync } from './EditModal';
import HikingEditVacanciesRow from './Row';
import { viewVacancyAsync } from './ViewModal';
import {
  deleteVacancy,
  getAllPositions,
  getHikingVacancies,
} from '../../@services/hikingPositionsAndVacancies.service';
import {
  IHikingPositionFull,
  IHikingVacancy,
} from '../../@types/hikingPositionsAndVacancies.types';

function HikingEditVacancies() {
  const [vacancies, setVacancies] = React.useState<IHikingVacancy[]>([]);
  const [positions, setPositions] = React.useState<IHikingPositionFull[]>([]);

  const hikingContext = React.useContext(HikingContext);

  React.useEffect(() => {
    const fetch = async () => {
      if (!hikingContext?.id) return;
      getAllPositions().then(setPositions);
      getHikingVacancies(hikingContext.id).then(setVacancies);
    };
    fetch();
  }, [hikingContext?.id]);

  const handleAdd = () => {
    if (!hikingContext) return;
    confirmModal({
      children: (closeModal: any) => (
        <PohList
          data={positions
            .filter((pos) => !vacancies.map((x) => x.position.id).includes(pos.id))
            .map((pos) => ({
              key: pos.id,
              content: pos.name,
              title: pos.description,
              onClick: async () => {
                const newVacancy = await addOrChangeVacancyAsync(
                  {
                    id: 0,
                    comment: '',
                    deadline: hikingContext.start,
                    isActive: true,
                    responsesCount: 0,
                    position: pos,
                  },
                  hikingContext,
                );
                closeModal();
                setVacancies((cur) => [...cur, newVacancy]);
                success(`Добавлен ${pos.name}`);
              },
            }))}
        />
      ),
      footer: null,
    });
  };

  const deleteHandler = async (vacancy: IHikingVacancy) => {
    if (!hikingContext) return;
    const res = await deleteVacancy(hikingContext.id, vacancy.id);
    res && setVacancies((cur) => cur.filter((x) => x.id !== vacancy.id));
  };
  const editHandler = async (vacancy: IHikingVacancy) => {
    if (!hikingContext) return;
    const updatedVacancy = await addOrChangeVacancyAsync(vacancy, hikingContext);
    setVacancies((cur) => cur.map((c) => (c.id === vacancy.id ? updatedVacancy : c)));
    success(`Сохранено`);
  };
  const viewHandler = async (vacancy: IHikingVacancy) => {
    if (!hikingContext) return;
    viewVacancyAsync(vacancy, hikingContext);
  };
  if (vacancies == null) {
    return <PageLoader />;
  }
  if (!hikingContext) return <div>Wrong hiking context</div>;

  return (
    <div className="pt-3">
      {!vacancies?.length && <Empty>Пока нет вакансий для похода</Empty>}
      <PohList
        data={vacancies.map((x) => ({
          key: x.id,
          content: (
            <HikingEditVacanciesRow
              vacancy={x}
              onEdit={editHandler}
              onDelete={deleteHandler}
              onView={viewHandler}
            />
          ),
        }))}
      />
      <PohButton onClick={handleAdd} className="mt-3">
        Добавить
      </PohButton>
    </div>
  );
}

export default HikingEditVacancies;
