import React from 'react';

import clsx from 'clsx';

import styles from './styles.module.less';

interface IScheduleHourProps extends React.HTMLAttributes<HTMLDivElement> {
  hour: number;
  onDropSchedule: (id: number, isForCopy: boolean, minutes: number) => void;
}

const ScheduleHour: React.FC<IScheduleHourProps> = ({ hour, onDropSchedule, ...rest }) => {
  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.currentTarget.classList.add(styles.drag);
  };
  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.currentTarget.classList.remove(styles.drag);
  };
  const handleDrop = async (e: React.DragEvent) => {
    e.preventDefault();
    handleDragLeave(e);

    const id = +e.dataTransfer.getData('plain/text');
    const copy = e.dataTransfer.getData('plain/copy');

    onDropSchedule(
      +id,
      !!copy,
      e.ctrlKey
        ? 0
        : Math.round(e.clientY - (e.target as HTMLDivElement).getBoundingClientRect().y),
    );
  };
  return (
    <div
      {...rest}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      data-hour={hour.toString().padStart(2, '0')}
      className={clsx(styles.hour)}
    ></div>
  );
};

export default ScheduleHour;
